    const std::string sampledSource="fragment float4 blur_main(V i[[stage_in]],texture2d<float> t[[texture(0)]],sampler s[[sampler(0)]]){"+std::string(depthSample?"float z=t.sample(s,i.uv).r;return float4(z,z,z,1);":"return t.sample(s,i.uv);")+"}\n";
