        require(pixels(floatResolved)==floatPixels,"Store-and-resolve failed to preserve multisample MRT samples across encoders");
        c.SetColourSurface(0,&reverse.GetSurface());c.SetColourSurface(1,nullptr);c.SetDepthStencilSurface(nullptr);c.BeginScene();c.SetViewport(C_Viewport(2,3,4,5));c.Clear(E_Clear_Colour,0xff800000);reverse.Resolve();c.EndScene();const auto cleared=pixels(floatResolved);
